css:
:scope{display:block;width:100%}.pw{--bg:#0F0E0C;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#8E4A30;--ol:#C2B8A6;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#EDE6D8;--tx:#0F0E0C;--lb:#3A3531;--rl:#8E4A30;--ol:#0F0E0C}.pw[data-ground="umber"]{--bg:#3A3531;--rl:#C2B8A6}.pw[data-ground="oxblood"]{--bg:#4A1C18;--rl:#C2B8A6}.pw[data-ground="clay"]{--bg:#8E4A30;--lb:#EDE6D8;--rl:#EDE6D8;--ol:#EDE6D8}.pw[data-ground="olive"]{--bg:#3C402F;--rl:#C2B8A6}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:112px 32px;display:flex;flex-wrap:wrap;gap:64px;align-items:flex-start}
.pw__pic{flex:1 1 360px;min-width:0;height:500px;overflow:hidden;line-height:0}.pw__pic img{display:block;width:100%;height:100%;object-fit:cover}
.pw__ph{background:#C2B8A6;display:flex;align-items:center;justify-content:center;text-align:center;font-family:var(--os-font-label);font-size:12px;letter-spacing:.24em;color:#3A3531;line-height:normal}
.pw__tx{flex:999 1 460px;min-width:0}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:2px;background:var(--rl);margin:28px 0 32px}
.pw__tx>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.05;color:var(--tx)}
.pw__ps p{margin:18px 0 0;font-size:21px;line-height:1.55}.pw__ps p:first-child{margin-top:24px}
.pw__nl{margin:36px 0 0;font-family:var(--os-font-label);font-size:11px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__names{margin:12px 0 0;font-size:19px;line-height:1.6;color:var(--lb)}
.pw__names span+span::before{content:"\00b7";margin:0 .5em}
.pw__btns{display:flex;flex-wrap:wrap;gap:16px;margin-top:36px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;line-height:normal;color:var(--tx);border:1px solid var(--ol);padding:16px 24px}
.pw__btn:focus-visible{outline:2px solid var(--tx);outline-offset:3px}
@media (max-width:767px){.pw__in{padding:56px 20px;gap:36px}.pw__pic{flex-basis:100%;height:420px}.pw__tx{flex-basis:100%}.pw__rule{width:48px;margin:24px 0}.pw__h2{font-size:44px}.pw__ps p{font-size:19px}.pw__nl{font-size:11px}.pw__names{font-size:18px}.pw__btns{flex-direction:column}.pw__btn{text-align:center}}
